templates.react:
export function ArticleLayout({
  title = "{{title}}",
  showToc = {{showToc}},
  showByline = {{showByline}},
  width = "{{width}}",
  accent = "{{accent}}",
}) {
  const maxWidth = width === "wide" ? "74ch" : "52ch";
  return (
    <div style={{ display: "flex", gap: 32, font: "16px/1.7 system-ui, sans-serif", color: "#241430", padding: 24 }}>
      {showToc && (
        <nav aria-label="Table of contents" style={{ flex: "0 0 160px", fontSize: 13 }}>
          <p style={{ fontWeight: 700, margin: "0 0 8px", textTransform: "uppercase", letterSpacing: "0.04em", color: "#241430aa" }}>On this page</p>
          <ul style={{ listStyle: "none", margin: 0, padding: 0, display: "flex", flexDirection: "column", gap: 6 }}>
            <li><a href="#overview" style={{ color: "#241430" }}>Overview</a></li>
            <li><a href="#details" style={{ color: "#241430" }}>Details</a></li>
            <li><a href="#summary" style={{ color: "#241430" }}>Summary</a></li>
          </ul>
        </nav>
      )}
      <article style={{ maxWidth: maxWidth }}>
        <h1 style={{ margin: "0 0 8px", fontSize: 30, fontWeight: 800, color: accent }}>{title}</h1>
        {showByline && <p style={{ margin: "0 0 20px", color: "#241430aa", fontSize: 14 }}>By Jordan Ames &middot; 5 min read</p>}
        <p style={{ margin: "0 0 16px", color: "#241430dd" }}>Long-form content flows in a single measured column, set for sustained reading rather than scanning.</p>
        <p style={{ margin: "0 0 16px", color: "#241430dd" }}>Paragraph spacing, line length and a restrained type scale keep attention on the text itself.</p>
      </article>
    </div>
  );
}
